package main

import (
	"fmt"
	"sort"
	"strings"
)

func renderBundleDart(input bundleGenerationInput) []byte {
	var b strings.Builder
	b.WriteString("// Code generated by codegen_graphql_app_client. DO NOT EDIT.\n")
	fmt.Fprintf(&b, "// ContractGraph SHA256: %s\n", input.graphDigest)
	fmt.Fprintf(&b, "// Persisted registry SHA256: %s\n\n", input.registryDigest)
	b.WriteString("import 'package:quwoquan_cloud_contracts/quwoquan_cloud_contracts.dart';\n\n")
	renderDescriptorTypes(&b)
	b.WriteString("abstract final class AppPersistedGraphQLQueries {\n")
	fmt.Fprintf(&b, "  static const String registrySha256 = %s;\n", dartString(input.registryDigest))
	fmt.Fprintf(&b, "  static const String registryCandidateDigest = %s;\n", dartString(input.registry.CandidateDigest))
	fmt.Fprintf(&b, "  static const String contractGraphSha256 = %s;\n", dartString(input.graphDigest))
	fmt.Fprintf(&b, "  static const String schemaDigest = %s;\n", dartString(input.schemaDigest))
	for _, query := range input.queries {
		renderQueryDescriptor(&b, query, input.schemaDigest)
	}
	b.WriteString("  static const List<PersistedGraphQLQueryDescriptor> all = <PersistedGraphQLQueryDescriptor>[\n")
	for _, query := range input.queries {
		fmt.Fprintf(&b, "    %s,\n", lowerDartIdentifier(query.entry.OperationName))
	}
	b.WriteString("  ];\n")
	b.WriteString("  static const List<String> assemblyProjectionFields = <String>[\n")
	projectionFields := append([]string(nil), input.projection.FieldNames...)
	sort.Strings(projectionFields)
	for _, field := range projectionFields {
		fmt.Fprintf(&b, "    %s,\n", dartString(field))
	}
	b.WriteString("  ];\n")
	b.WriteString("  static const List<PersistedGraphQLAssemblyMapping> assemblyMappings = <PersistedGraphQLAssemblyMapping>[\n")
	for _, mapping := range input.plan.AssemblyMappings {
		renderAssemblyMapping(&b, mapping)
	}
	b.WriteString("  ];\n")
	b.WriteString("}\n\n")
	renderGeneratedClient(&b, input)
	renderBundleRuntime(&b)
	renderGatewayContract(&b, input.gateway, input.ownerOperation)
	return []byte(b.String())
}

func renderDescriptorTypes(b *strings.Builder) {
	b.WriteString("enum PersistedGraphQLAssemblyStrategy { mergeObject, assignKey, replace }\n\n")
	b.WriteString("final class PersistedGraphQLAssemblySource {\n")
	b.WriteString("  const PersistedGraphQLAssemblySource({required this.sourceField, required this.strategy, this.targetKey});\n")
	b.WriteString("  final String sourceField;\n  final PersistedGraphQLAssemblyStrategy strategy;\n  final String? targetKey;\n}\n\n")
	b.WriteString("final class PersistedGraphQLAssemblyMapping {\n")
	b.WriteString("  const PersistedGraphQLAssemblyMapping({required this.targetField, this.presenceSourceField, required this.sources});\n")
	b.WriteString("  final String targetField;\n  final String? presenceSourceField;\n  final List<PersistedGraphQLAssemblySource> sources;\n}\n\n")
	b.WriteString("final class PersistedGraphQLQueryDescriptor {\n")
	b.WriteString("  const PersistedGraphQLQueryDescriptor({required this.operationName, required this.canonicalOperationId, required this.sha256Hash, required this.schemaDigest, required this.costModelVersion, required this.costPlanDigest, required this.sloRef, required this.responseKey, required this.role, required this.selectedFields, required this.supportedContentTypes, required this.requiredForContentTypes, required this.depth, required this.topLevelFields, required this.worstCaseComplexity, required this.variablesMaxBytes, required this.maxOwnerCalls, required this.maxBatchKeys, required this.maxResponseBytes});\n")
	b.WriteString("  final String operationName;\n  final String canonicalOperationId;\n  final String sha256Hash;\n  final String schemaDigest;\n  final String costModelVersion;\n  final String costPlanDigest;\n  final String sloRef;\n  final String responseKey;\n  final String role;\n")
	b.WriteString("  final List<String> selectedFields;\n  final List<String> supportedContentTypes;\n  final List<String> requiredForContentTypes;\n")
	b.WriteString("  final int depth;\n  final int topLevelFields;\n  final int worstCaseComplexity;\n  final int variablesMaxBytes;\n  final int maxOwnerCalls;\n  final int maxBatchKeys;\n  final int maxResponseBytes;\n}\n\n")
}

func renderQueryDescriptor(b *strings.Builder, query bundleQueryInput, schemaDigest string) {
	entry := query.entry
	binding := *entry.AppClientBundle
	fmt.Fprintf(b, "  static const PersistedGraphQLQueryDescriptor %s = PersistedGraphQLQueryDescriptor(\n", lowerDartIdentifier(entry.OperationName))
	fmt.Fprintf(b, "    operationName: %s, canonicalOperationId: %s, sha256Hash: %s,\n", dartString(entry.OperationName), dartString(entry.CanonicalOperationID), dartString(entry.SHA256Hash))
	fmt.Fprintf(b, "    schemaDigest: %s, costModelVersion: %s, costPlanDigest: %s, sloRef: %s,\n", dartString(schemaDigest), dartString(entry.CostModelVersion), dartString(entry.CostPlanDigest), dartString(entry.Cost.SLORef))
	fmt.Fprintf(b, "    responseKey: %s, role: %s,\n", dartString(query.responseKey), dartString(binding.Role))
	renderStringList(b, "selectedFields", query.selectedFields, 4)
	renderStringList(b, "supportedContentTypes", binding.SupportedContentTypes, 4)
	renderStringList(b, "requiredForContentTypes", binding.RequiredForContentTypes, 4)
	fmt.Fprintf(b, "    depth: %d, topLevelFields: %d, worstCaseComplexity: %d, variablesMaxBytes: %d,\n", entry.Cost.Depth, entry.Cost.TopLevelFields, entry.Cost.Complexity, entry.Cost.VariablesMaxBytes)
	fmt.Fprintf(b, "    maxOwnerCalls: %d, maxBatchKeys: %d, maxResponseBytes: %d,\n", entry.Cost.MaxOwnerCalls, entry.Cost.MaxBatchKeys, entry.Cost.MaxResponseBytes)
	b.WriteString("  );\n")
}

func renderAssemblyMapping(b *strings.Builder, mapping assemblyMapping) {
	b.WriteString("    PersistedGraphQLAssemblyMapping(\n")
	fmt.Fprintf(b, "      targetField: %s,\n", dartString(mapping.TargetField))
	if mapping.PresenceSourceField != "" {
		fmt.Fprintf(b, "      presenceSourceField: %s,\n", dartString(mapping.PresenceSourceField))
	}
	b.WriteString("      sources: <PersistedGraphQLAssemblySource>[\n")
	for _, source := range mapping.Sources {
		fmt.Fprintf(b, "        PersistedGraphQLAssemblySource(sourceField: %s, strategy: PersistedGraphQLAssemblyStrategy.%s", dartString(source.SourceField), lowerCamelStrategy(source.Strategy))
		if source.TargetKey != "" {
			fmt.Fprintf(b, ", targetKey: %s", dartString(source.TargetKey))
		}
		b.WriteString("),\n")
	}
	b.WriteString("      ],\n    ),\n")
}

func renderGeneratedClient(b *strings.Builder, input bundleGenerationInput) {
	baseName := lowerDartIdentifier(input.plan.Base.OperationName)
	b.WriteString("final class GeneratedPersistedGraphQLClient {\n  const GeneratedPersistedGraphQLClient(this._executor);\n  final CloudOperationExecutor _executor;\n\n")
	b.WriteString("  Future<ContentPostDetailSlice> contentPostDetail(ContentPostDetailQuery request, {required CloudOperationInvocationContext context}) async {\n")
	fmt.Fprintf(b, "    const baseDescriptor = AppPersistedGraphQLQueries.%s;\n", baseName)
	b.WriteString("    final base = await _executeSlice(baseDescriptor, request, context);\n")
	b.WriteString("    final contentTypeValue = base['contentType'];\n    if (contentTypeValue is! String || !baseDescriptor.supportedContentTypes.contains(contentTypeValue)) {\n      throw const FormatException('ContentPostDetail bundle returned unsupported contentType');\n    }\n")
	b.WriteString("    final assembled = <String, Object?>{};\n    _mergeSlice(assembled, base, baseDescriptor.operationName);\n")
	b.WriteString("    for (final descriptor in AppPersistedGraphQLQueries.all) {\n      if (descriptor.role == 'extension' && descriptor.requiredForContentTypes.contains(contentTypeValue)) {\n        _mergeSlice(assembled, await _executeSlice(descriptor, request, context), descriptor.operationName);\n      }\n    }\n")
	b.WriteString("    _applyAssemblyMappings(assembled, AppPersistedGraphQLQueries.assemblyMappings);\n")
	b.WriteString("    _requireExactFields(assembled, AppPersistedGraphQLQueries.assemblyProjectionFields, 'ContentPostDetailSlice');\n")
	b.WriteString("    return decodeContentPostDetailSlice(assembled);\n  }\n\n")
	b.WriteString("  Future<Map<String, Object?>> _executeSlice(PersistedGraphQLQueryDescriptor descriptor, ContentPostDetailQuery request, CloudOperationInvocationContext context) {\n")
	b.WriteString("    return _executor.send<Map<String, Object?>>(_persistedGraphQLTransportOperation, context: context, responseDecoder: (response) => _decodeSliceResponse(response, descriptor), requestEncoder: () => CloudOperationRequestPayload(body: <String, Object?>{'operationName': descriptor.operationName, 'variables': request.toWire(), 'extensions': <String, Object?>{'persistedQuery': <String, Object?>{'version': 1, 'sha256Hash': descriptor.sha256Hash}}}));\n  }\n}\n\n")
}

func renderBundleRuntime(b *strings.Builder) {
	b.WriteString("Map<String, Object?> _decodeSliceResponse(Object? response, PersistedGraphQLQueryDescriptor descriptor) {\n")
	b.WriteString("  final envelope = _requiredGraphQLObject(response, 'GraphQLReadResponse');\n  if (envelope.length != 1 || !envelope.containsKey('data')) throw const FormatException('GraphQLReadResponse must contain only data');\n")
	b.WriteString("  final data = _requiredGraphQLObject(envelope['data'], 'GraphQLReadResponse.data');\n  if (data.length != 1 || !data.containsKey(descriptor.responseKey)) throw FormatException('GraphQLReadResponse.data must contain only ${descriptor.responseKey}');\n")
	b.WriteString("  final slice = _requiredGraphQLObject(data[descriptor.responseKey], descriptor.responseKey);\n  _requireExactFields(slice, descriptor.selectedFields, descriptor.operationName);\n  return slice;\n}\n\n")
	b.WriteString("void _mergeSlice(Map<String, Object?> target, Map<String, Object?> source, String operationName) {\n  for (final entry in source.entries) {\n    if (target.containsKey(entry.key)) {\n      if (target[entry.key] != entry.value) throw FormatException('$operationName conflicts on shared bundle identity ${entry.key}');\n      continue;\n    }\n    target[entry.key] = entry.value;\n  }\n}\n\n")
	b.WriteString("void _applyAssemblyMappings(Map<String, Object?> values, List<PersistedGraphQLAssemblyMapping> mappings) {\n  for (final mapping in mappings) {\n    final presentSources = mapping.sources.where((source) => values.containsKey(source.sourceField)).toList(growable: false);\n    if (presentSources.isEmpty) continue;\n    if (presentSources.length != mapping.sources.length || values.containsKey(mapping.targetField)) throw FormatException('partial/conflicting assembly mapping ${mapping.targetField}');\n")
	b.WriteString("    final presence = mapping.presenceSourceField == null ? null : values[mapping.presenceSourceField];\n    if (mapping.presenceSourceField != null && presence == null) {\n      for (final source in mapping.sources) {\n        final value = values[source.sourceField];\n        if (source.sourceField != mapping.presenceSourceField && !_isNullOrEmptyAssemblyValue(value)) throw FormatException('null presence source conflicts with ${source.sourceField}');\n        values.remove(source.sourceField);\n      }\n      values[mapping.targetField] = null;\n      continue;\n    }\n")
	b.WriteString("    Object? result;\n    final object = <String, Object?>{};\n    for (final source in mapping.sources) {\n      final value = values.remove(source.sourceField);\n      switch (source.strategy) {\n        case PersistedGraphQLAssemblyStrategy.replace:\n          result = value;\n          break;\n        case PersistedGraphQLAssemblyStrategy.mergeObject:\n          final incoming = _requiredGraphQLObject(value, source.sourceField);\n          for (final entry in incoming.entries) {\n            if (object.containsKey(entry.key)) throw FormatException('assembly key conflict ${entry.key}');\n            object[entry.key] = entry.value;\n          }\n          result = object;\n          break;\n        case PersistedGraphQLAssemblyStrategy.assignKey:\n          final key = source.targetKey;\n          if (key == null || object.containsKey(key)) throw FormatException('assembly assign_key conflict $key');\n          object[key] = value;\n          result = object;\n          break;\n      }\n    }\n    values[mapping.targetField] = result;\n  }\n}\n\n")
	b.WriteString("bool _isNullOrEmptyAssemblyValue(Object? value) => value == null || value is List && value.isEmpty || value is Map && value.isEmpty;\n\n")
	b.WriteString("void _requireExactFields(Map<String, Object?> value, List<String> required, String path) {\n  final actual = value.keys.toSet();\n  final expected = required.toSet();\n  if (actual.length != expected.length || !actual.containsAll(expected)) throw FormatException('$path fields differ from signed bundle plan');\n}\n\n")
	b.WriteString("Map<String, Object?> _requiredGraphQLObject(Object? value, String path) {\n  if (value is! Map) throw FormatException('$path must be an object');\n  final result = <String, Object?>{};\n  for (final entry in value.entries) {\n    if (entry.key is! String) throw FormatException('$path contains a non-string key');\n    result[entry.key as String] = entry.value;\n  }\n  return result;\n}\n\n")
}

func renderGatewayContract(b *strings.Builder, gateway graphOperation, owner appLockOperation) {
	b.WriteString("const CloudOperationContract _persistedGraphQLTransportOperation = CloudOperationContract(\n")
	fmt.Fprintf(b, "  canonicalOperationId: %s, localOperationId: %s, domain: %s, objectId: %s, kind: %s, facet: %s, facadeMethod: %s,\n", dartString(gateway.ID), dartString(gateway.LocalOperationID), dartString(gateway.Domain), dartString(gateway.ObjectID), dartString(gateway.Kind), dartString(gateway.Facet), dartString(gateway.FacadeMethod))
	b.WriteString("  aggregateOwner: '', mutationTarget: '', invariantTarget: '',\n")
	fmt.Fprintf(b, "  method: %s, pathTemplate: %s, authMode: %s, actorRequirement: %s, principal: %s, scopes: <String>[], permissions: <String>[], ownershipPolicy: %s,\n", dartString(gateway.Method), dartString(gateway.PathTemplate), dartString(gateway.AuthMode), dartString(gateway.ActorRequirement), dartString(gateway.Principal), dartString(gateway.OwnershipPolicy))
	fmt.Fprintf(b, "  commercialStatus: %s, commercialBlockReason: %s, timeoutMilliseconds: %d, cancellation: %s, retryMode: %s, maxAttempts: %d, idempotency: %s, versionPrecondition: '',\n", dartString(gateway.Commercial.Status), dartString(gateway.Commercial.BlockReason), gateway.Reliability.TimeoutMilliseconds, dartString(gateway.Reliability.Cancellation), dartString(gateway.Reliability.RetryMode), gateway.Reliability.MaxAttempts, dartString(gateway.Reliability.Idempotency))
	renderStringList(b, "errorCodes", gateway.ErrorCodes, 2)
	fmt.Fprintf(b, "  requestClassification: %s, responseClassification: %s, logPolicy: %s, telemetryMetric: %s, telemetryTrace: %t,\n", dartString(gateway.Privacy.RequestClassification), dartString(gateway.Privacy.ResponseClassification), dartString(gateway.Privacy.LogPolicy), dartString(gateway.Telemetry.Metric), gateway.Telemetry.Trace)
	renderStringList(b, "telemetryAttributes", gateway.Telemetry.Attributes, 2)
	fmt.Fprintf(b, "  latencyP95Milliseconds: %d, availabilityPercent: %v, requestEntity: %s, requestBodyKind: %s, transport: %s,\n", gateway.SLO.LatencyP95Milliseconds, gateway.SLO.AvailabilityPercent, dartString(gateway.RequestEntity), dartString(gateway.RequestBodyKind), dartString(gateway.Transport))
	b.WriteString("  requestPathBindings: <CloudOperationRequestBinding>[], requestQueryBindings: <CloudOperationRequestBinding>[], requestHeaderBindings: <CloudOperationRequestBinding>[], requestInjectedBindings: <CloudOperationRequestBinding>[],\n")
	fmt.Fprintf(b, "  responseEntity: %s, responseBody: %s, responseBodyKind: %s, maximumResponseBodyBytes: %d,\n", dartString(gateway.ResponseEntity), dartString(gateway.ResponseBody), dartString(gateway.ResponseBodyKind), gateway.ResponseAdmission.MaximumBodyBytes)
	renderStringList(b, "surfaceIds", owner.SurfaceIDs, 2)
	b.WriteString(");\n")
}

func renderStringList(b *strings.Builder, name string, values []string, indent int) {
	spaces := strings.Repeat(" ", indent)
	fmt.Fprintf(b, "%s%s: <String>[", spaces, name)
	for _, value := range values {
		fmt.Fprintf(b, "%s,", dartString(value))
	}
	b.WriteString("],\n")
}

func lowerDartIdentifier(value string) string {
	if value == "" {
		return value
	}
	return strings.ToLower(value[:1]) + value[1:]
}

func lowerCamelStrategy(value string) string {
	parts := strings.Split(value, "_")
	for index := 1; index < len(parts); index++ {
		parts[index] = strings.ToUpper(parts[index][:1]) + parts[index][1:]
	}
	return strings.Join(parts, "")
}
